const providerOAuthCrypto = require('crypto');
const PROVIDER_OAUTH_REQUIRED_SCOPE = 'salesforce.integration';
const PROVIDER_OAUTH_TOKEN_TTL_SECONDS = 900;

function providerOAuthEnv(name) {
  try { return String($env[name] || ''); } catch (error) { return ''; }
}

function providerOAuthHeader(headers, name) {
  const target = name.toLowerCase();
  for (const [key, value] of Object.entries(headers || {})) {
    if (String(key).toLowerCase() === target) return Array.isArray(value) ? value[0] : value;
  }
  return '';
}

function providerOAuthScopes(value) {
  return [...new Set(String(value || '').trim().split(/\s+/).filter(Boolean))];
}

function providerOAuthBase64Url(value) {
  return Buffer.from(value).toString('base64').replace(/=/g, '').replace(/\+/g, '-').replace(/\//g, '_');
}

function providerOAuthDecodeSegment(segment) {
  if (!/^[A-Za-z0-9_-]+$/.test(String(segment || ''))) throw new Error('invalid base64url');
  const padding = (4 - (segment.length % 4)) % 4;
  const decoded = Buffer.from(segment + '='.repeat(padding), 'base64');
  if (providerOAuthBase64Url(decoded) !== segment) throw new Error('non-canonical base64url');
  return decoded;
}

function providerOAuthFailure(statusCode, error, description) {
  return { ok: false, statusCode, body: { error, error_description: description } };
}

function providerOAuthInvalidToken() {
  return providerOAuthFailure(401, 'invalid_token', 'The access token is invalid or expired.');
}

function validateProviderBearerJwt(request) {
  const jwtSecret = providerOAuthEnv('RENOV_OAUTH_JWT_SECRET');
  const issuer = providerOAuthEnv('RENOV_OAUTH_ISSUER');
  const audience = providerOAuthEnv('RENOV_OAUTH_AUDIENCE');
  const configuredClientId = providerOAuthEnv('RENOV_OAUTH_CLIENT_ID');
  const configuredScopes = providerOAuthScopes(providerOAuthEnv('RENOV_OAUTH_SCOPE'));
  const allowedClientIds = providerOAuthEnv('RENOV_PROVIDER_CLIENT_IDS')
    .split(',')
    .map((value) => value.trim().toLowerCase())
    .filter(Boolean);

  if (!jwtSecret || !issuer || !audience || !configuredClientId
      || !configuredScopes.includes(PROVIDER_OAUTH_REQUIRED_SCOPE)
      || allowedClientIds.length === 0) {
    return providerOAuthFailure(503, 'server_error', 'OAuth server configuration is unavailable.');
  }

  const headers = request && request.headers && typeof request.headers === 'object' ? request.headers : {};
  const authorization = String(providerOAuthHeader(headers, 'authorization') || '');
  const bearerMatch = authorization.match(/^Bearer[ \t]+([^ \t]+)[ \t]*$/i);
  const xClientId = String(providerOAuthHeader(headers, 'x-client-id') || '').trim().toLowerCase();
  if (!bearerMatch || !xClientId || !allowedClientIds.includes(xClientId)) return providerOAuthInvalidToken();

  const token = bearerMatch[1];
  const parts = token.split('.');
  if (parts.length !== 3) return providerOAuthInvalidToken();

  let header;
  let payload;
  let signature;
  try {
    header = JSON.parse(providerOAuthDecodeSegment(parts[0]).toString('utf8'));
    payload = JSON.parse(providerOAuthDecodeSegment(parts[1]).toString('utf8'));
    signature = providerOAuthDecodeSegment(parts[2]);
  } catch (error) {
    return providerOAuthInvalidToken();
  }
  if (!header || typeof header !== 'object' || Array.isArray(header) || header.alg !== 'HS256') {
    return providerOAuthInvalidToken();
  }
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return providerOAuthInvalidToken();

  const expectedSignature = providerOAuthCrypto
    .createHmac('sha256', jwtSecret)
    .update(parts[0] + '.' + parts[1], 'utf8')
    .digest();
  if (signature.length !== expectedSignature.length
      || !providerOAuthCrypto.timingSafeEqual(signature, expectedSignature)) {
    return providerOAuthInvalidToken();
  }

  if (payload.iss !== issuer || payload.aud !== audience
      || typeof payload.sub !== 'string' || typeof payload.client_id !== 'string'
      || payload.sub !== configuredClientId || payload.client_id !== configuredClientId
      || payload.sub !== payload.client_id) {
    return providerOAuthInvalidToken();
  }

  const tokenScopes = providerOAuthScopes(payload.scope);
  if (!tokenScopes.includes(PROVIDER_OAUTH_REQUIRED_SCOPE)
      || !tokenScopes.every((scope) => configuredScopes.includes(scope))) {
    return providerOAuthFailure(403, 'insufficient_scope', 'The access token lacks the required scope.');
  }

  const numericDatesAreValid = Number.isSafeInteger(payload.iat)
    && Number.isSafeInteger(payload.nbf)
    && Number.isSafeInteger(payload.exp);
  const now = Math.floor(Date.now() / 1000);
  if (!numericDatesAreValid
      || payload.nbf !== payload.iat
      || payload.exp - payload.iat !== PROVIDER_OAUTH_TOKEN_TTL_SECONDS
      || payload.iat > now
      || payload.nbf > now
      || payload.exp <= now) {
    return providerOAuthInvalidToken();
  }

  return {
    ok: true,
    clientId: payload.client_id,
    providerClientId: xClientId,
    scope: tokenScopes.join(' '),
    claims: payload,
  };
}

const providerOAuthRequest = $input.first().json || {};
const providerOAuthAuth = validateProviderBearerJwt(providerOAuthRequest);
if (!providerOAuthAuth.ok) {
  return [{ json: { statusCode: providerOAuthAuth.statusCode, body: providerOAuthAuth.body, authorized: false } }];
}

const INTAKE_SQL = "WITH payload AS (\n  SELECT\n    $1::jsonb AS data,\n    lower(btrim($2::text)) AS client_id,\n    btrim($3::text) AS endpoint\n), normalized AS (\n  SELECT\n    data->>'sf_dispatch_id' AS sf_dispatch_id,\n    nullif(data->>'sf_campaign_id', '') AS sf_campaign_id,\n    data->>'sf_brand' AS sf_brand,\n    (data->>'campaign_base')::renovation_dev.campaign_base AS campaign_base,\n    data->>'template_name' AS template_name,\n    data->>'sf_owner_id' AS sf_owner_id,\n    coalesce((data->>'dev_defer_sender')::boolean, false) AS dev_defer_sender,\n    coalesce((data->>'requested_count')::integer, 0) AS requested_count,\n    coalesce(data->'rejected_items', '[]'::jsonb) AS validator_rejections,\n    coalesce(data->'items', '[]'::jsonb) AS items\n  FROM payload\n), existing_dispatch AS (\n  SELECT dispatch.*\n    FROM renovation_dev.quicklink_campaign_dispatches dispatch\n    JOIN normalized n ON n.sf_dispatch_id = dispatch.sf_dispatch_id\n), owner_row AS (\n  INSERT INTO renovation_dev.advisors (salesforce_user_id, full_name, active)\n  SELECT n.sf_owner_id, n.sf_owner_id, true\n    FROM normalized n\n   WHERE NOT EXISTS (SELECT 1 FROM existing_dispatch)\n  ON CONFLICT (salesforce_user_id) DO UPDATE\n    SET active = true,\n        synced_at = now()\n  RETURNING id, salesforce_user_id\n), campaign_row AS (\n  INSERT INTO renovation_dev.campaigns AS campaign (\n    name, base, month, vehicle_brand, template_pool, advisor_id, active\n  )\n  SELECT\n    'SF ' || n.sf_owner_id || ' ' || n.sf_brand || ' ' || n.campaign_base,\n    n.campaign_base,\n    date_trunc('month', now() AT TIME ZONE 'America/Guayaquil')::date,\n    n.sf_brand,\n    ARRAY[n.template_name]::text[],\n    owner_row.id,\n    true\n  FROM normalized n\n  JOIN owner_row ON owner_row.salesforce_user_id = n.sf_owner_id\n  ON CONFLICT (advisor_id, vehicle_brand, base, month)\n    WHERE advisor_id IS NOT NULL AND vehicle_brand IS NOT NULL\n  DO UPDATE\n    SET template_pool = CASE\n          WHEN campaign.template_pool @> ARRAY[EXCLUDED.template_pool[1]]::text[]\n            THEN campaign.template_pool\n          ELSE campaign.template_pool || EXCLUDED.template_pool[1]\n        END,\n        active = true,\n        updated_at = now()\n  RETURNING id, advisor_id\n), incoming_items AS (\n  SELECT\n    item_index,\n    sf_account_id,\n    sf_vehicle_id,\n    nullif(sf_contract_id, '') AS sf_contract_id,\n    phone,\n    coalesce(merge_fields, '{}'::jsonb) AS merge_fields\n  FROM normalized n,\n       jsonb_to_recordset(n.items) AS item(\n         item_index integer,\n         sf_account_id text,\n         sf_vehicle_id text,\n         sf_contract_id text,\n         phone text,\n         merge_fields jsonb\n       )\n), item_decisions AS (\n  SELECT\n    item.*,\n    account.id AS account_id,\n    vehicle.id AS vehicle_id,\n    contract.id AS contract_id,\n    CASE\n      WHEN account.id IS NULL OR vehicle.id IS NULL THEN 'UNKNOWN_ACCOUNT'\n      WHEN account.campaign_paused THEN 'CAMPAIGN_PAUSED'\n      WHEN account.opportunity_closed OR vehicle.opportunity_closed THEN 'OPPORTUNITY_CLOSED'\n      ELSE NULL\n    END AS reject_reason\n  FROM incoming_items item\n  LEFT JOIN renovation_dev.quicklink_account_assignments account\n    ON account.salesforce_contact_id = item.sf_account_id\n   AND account.deleted_at IS NULL\n  LEFT JOIN renovation_dev.quicklink_vehicle_assignments vehicle\n    ON vehicle.salesforce_vehicle_id = item.sf_vehicle_id\n   AND vehicle.customer_id = account.id\n   AND vehicle.deleted_at IS NULL\n  LEFT JOIN renovation_dev.quicklink_contract_assignments contract\n    ON contract.sf_contract_id = item.sf_contract_id\n   AND contract.account_id = account.id\n   AND contract.deleted_at IS NULL\n), db_rejections AS (\n  SELECT coalesce(jsonb_agg(\n    jsonb_build_object(\n      'sf_accountId', sf_account_id,\n      'sf_vehicleId', sf_vehicle_id,\n      'reason', reject_reason\n    ) ORDER BY item_index\n  ), '[]'::jsonb) AS value\n  FROM item_decisions\n  WHERE reject_reason IS NOT NULL\n), counts AS (\n  SELECT\n    count(*) FILTER (WHERE reject_reason IS NULL)::integer AS accepted_count,\n    count(*) FILTER (WHERE reject_reason IS NOT NULL)::integer AS db_rejected_count\n  FROM item_decisions\n), dispatch_row AS (\n  INSERT INTO renovation_dev.quicklink_campaign_dispatches (\n    sf_dispatch_id,\n    client_id,\n    campaign_id,\n    advisor_id,\n    salesforce_campaign_id,\n    campaign_name,\n    segment_month,\n    template_name,\n    status,\n    requested_count,\n    accepted_count,\n    rejected_count,\n    rejections,\n    process_after,\n    last_error\n  )\n  SELECT\n    n.sf_dispatch_id,\n    p.client_id,\n    campaign_row.id,\n    campaign_row.advisor_id,\n    n.sf_campaign_id,\n    n.sf_brand,\n    n.campaign_base,\n    n.template_name,\n    CASE\n      WHEN counts.accepted_count > 0 THEN 'queued'::renovation_dev.dispatch_status\n      ELSE 'completed'::renovation_dev.dispatch_status\n    END,\n    n.requested_count,\n    counts.accepted_count,\n    jsonb_array_length(n.validator_rejections) + counts.db_rejected_count,\n    n.validator_rejections || db_rejections.value,\n    now(),\n    CASE WHEN n.dev_defer_sender THEN 'dev_deferred_pending' ELSE NULL END\n  FROM normalized n, payload p, counts, db_rejections, campaign_row\n  WHERE NOT EXISTS (SELECT 1 FROM existing_dispatch)\n  RETURNING *\n), target_insert AS (\n  INSERT INTO renovation_dev.campaign_targets (campaign_id, customer_id, vehicle_id)\n  SELECT dispatch_row.campaign_id, decision.account_id, decision.vehicle_id\n    FROM item_decisions decision, dispatch_row\n   WHERE decision.reject_reason IS NULL\n  ON CONFLICT (campaign_id, customer_id, vehicle_id) DO NOTHING\n  RETURNING id, campaign_id, customer_id, vehicle_id\n), target_rows AS (\n  SELECT id, customer_id, vehicle_id\n    FROM target_insert\n  UNION ALL\n  SELECT target.id, target.customer_id, target.vehicle_id\n    FROM renovation_dev.campaign_targets target\n    JOIN dispatch_row ON dispatch_row.campaign_id = target.campaign_id\n    JOIN item_decisions decision\n      ON decision.account_id = target.customer_id\n     AND decision.vehicle_id = target.vehicle_id\n   WHERE decision.reject_reason IS NULL\n     AND NOT EXISTS (\n       SELECT 1\n         FROM target_insert inserted\n        WHERE inserted.campaign_id = target.campaign_id\n          AND inserted.customer_id = target.customer_id\n          AND inserted.vehicle_id = target.vehicle_id\n     )\n), item_insert AS (\n  INSERT INTO renovation_dev.quicklink_campaign_dispatch_items (\n    dispatch_id,\n    campaign_target_id,\n    template_name,\n    status,\n    salesforce_customer_id,\n    metadata\n  )\n  SELECT\n    dispatch_row.id,\n    target_rows.id,\n    dispatch_row.template_name,\n    'pending'::renovation_dev.delivery_status,\n    decision.sf_account_id,\n    jsonb_build_object(\n      'sf_dispatchId', dispatch_row.sf_dispatch_id,\n      'sf_vehicleId', decision.sf_vehicle_id,\n      'sf_contractId', decision.sf_contract_id,\n      'phone', decision.phone,\n      'mergeFields', decision.merge_fields,\n      'itemIndex', decision.item_index\n    )\n  FROM item_decisions decision\n  JOIN target_rows\n    ON target_rows.customer_id = decision.account_id\n   AND target_rows.vehicle_id = decision.vehicle_id\n  JOIN dispatch_row ON true\n  WHERE decision.reject_reason IS NULL\n  ON CONFLICT (dispatch_id, campaign_target_id, template_name) DO NOTHING\n  RETURNING id\n), selected_dispatch AS (\n  SELECT * FROM dispatch_row\n  UNION ALL\n  SELECT * FROM existing_dispatch\n  LIMIT 1\n)\nSELECT\n  CASE\n    WHEN EXISTS (SELECT 1 FROM existing_dispatch WHERE status IN ('queued', 'running')) THEN 409\n    WHEN EXISTS (SELECT 1 FROM existing_dispatch) THEN 200\n    ELSE 202\n  END AS status_code,\n  CASE\n    WHEN EXISTS (SELECT 1 FROM existing_dispatch WHERE status IN ('queued', 'running')) THEN 'DISPATCH_IN_PROGRESS'\n    WHEN EXISTS (SELECT 1 FROM existing_dispatch) THEN 'ALREADY_PROCESSED'\n    ELSE 'ACCEPTED'\n  END AS code,\n  CASE\n    WHEN EXISTS (SELECT 1 FROM existing_dispatch WHERE status IN ('queued', 'running')) THEN 'El dispatch ya esta en procesamiento.'\n    WHEN EXISTS (SELECT 1 FROM existing_dispatch) THEN 'El dispatch ya fue procesado anteriormente.'\n    ELSE 'Lote recibido y encolado.'\n  END AS message,\n  selected_dispatch.id::text AS job_id,\n  selected_dispatch.sf_dispatch_id,\n  selected_dispatch.status AS dispatch_status,\n  selected_dispatch.requested_count AS received,\n  selected_dispatch.accepted_count AS accepted,\n  selected_dispatch.rejected_count AS rejected,\n  selected_dispatch.rejections AS rejected_items,\n  coalesce((SELECT dev_defer_sender FROM normalized), false) AS dev_defer_sender,\n  coalesce((SELECT count(*)::integer FROM item_insert), 0) AS inserted_items\nFROM payload\nLEFT JOIN selected_dispatch ON true;\n";
// Intake deliberately does not call renovation_dev.check_provider_rate_limit;
// WF-02B throttles committed worker claims instead of rejecting valid requests.
const ENDPOINT = '/v1/campaigns/dispatch';
const MAX_ITEMS = 1500;
const MONTH_SEGMENTS = { previous: 'past_winback', current: 'current', next: 'future' };
const SENDER_SUPPORTED_TEMPLATES = Object.freeze(["renovacion_vencimiento_2026_v1","renovacion_vencimiento_2026_v2","renovacion_vencimiento_2026_v3"]);

function env(name, fallback = '') {
  try { return $env[name] || fallback; } catch (e) { return fallback; }
}

const request = $input.first().json;
const headers = request.headers ?? {};
const body = request.body ?? {};

function response(statusCode, responseBody) {
  return [{ json: { statusCode, body: responseBody } }];
}

function apiError(statusCode, code, message, details = []) {
  return response(statusCode, { code, message, details });
}

function isBlank(value) {
  return value === undefined || value === null || String(value).trim() === '';
}

function normalizePhone(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  if (raw.startsWith('+')) return '+' + raw.replace(/[^0-9]/g, '');
  let digits = raw.replace(/[^0-9]/g, '');
  if (digits.startsWith('00')) digits = digits.slice(2);
  if (digits.startsWith('593')) return '+' + digits;
  if (digits.startsWith('0') && digits.length === 10) return '+593' + digits.slice(1);
  if (digits.length === 9 && digits.startsWith('9')) return '+593' + digits;
  return '+' + digits;
}

function isE164(value) {
  return /^\+[1-9][0-9]{7,14}$/.test(String(value || ''));
}

function cleanString(value) {
  return String(value ?? '').trim();
}

function allowedTemplates() {
  const configured = env('RENOV_ALLOWED_HSM_TEMPLATES')
    .split(',')
    .map((value) => value.trim())
    .filter(Boolean);
  const requested = configured.length ? configured : SENDER_SUPPORTED_TEMPLATES;
  return SENDER_SUPPORTED_TEMPLATES.filter((template) => requested.includes(template));
}

function rejectItem(item, reason) {
  return {
    sf_accountId: cleanString(item?.sf_accountId) || null,
    sf_vehicleId: cleanString(item?.sf_vehicleId) || null,
    reason,
  };
}

if (!body || typeof body !== 'object' || Array.isArray(body)) {
  return apiError(400, 'INVALID_PAYLOAD', 'Body JSON requerido.');
}

const sfDispatchId = cleanString(body.sf_dispatchId);
const sfBrand = cleanString(body.sf_brand);
const monthSegment = cleanString(body.sf_monthSegment);
const templateName = cleanString(body.sf_templateId);
const sfOwnerId = cleanString(body.sf_ownerId);
const devDeferSender = body.dev_defer_sender === true;

if (devDeferSender) {
  const internalToken = env('RENOV_INTERNAL_TOKEN');
  const providedInternalToken = String(providerOAuthHeader(headers, 'x-internal-token') || '');
  if (env('RENOV_ENV', 'dev').toLowerCase() !== 'dev'
      || env('RENOV_DEV_DRY_RUN_SENDS', '').toLowerCase() !== 'true') {
    return apiError(422, 'SCHEDULING_NOT_SUPPORTED', 'dev_defer_sender solo existe en DEV dry-run.');
  }
  if (!internalToken) {
    return apiError(503, 'INTERNAL_ERROR', 'Falta RENOV_INTERNAL_TOKEN para la simulacion DEV.');
  }
  if (providedInternalToken !== internalToken) {
    return apiError(401, 'UNAUTHORIZED', 'X-Internal-Token invalido para la simulacion DEV.');
  }
}

const missingTopLevel = [];
if (!sfDispatchId) missingTopLevel.push('sf_dispatchId');
if (!sfBrand) missingTopLevel.push('sf_brand');
if (!monthSegment) missingTopLevel.push('sf_monthSegment');
if (!templateName) missingTopLevel.push('sf_templateId');
if (!sfOwnerId) missingTopLevel.push('sf_ownerId');
if (missingTopLevel.length) {
  return apiError(400, 'INVALID_PAYLOAD', 'Faltan campos obligatorios del dispatch.', missingTopLevel);
}

if (!Object.prototype.hasOwnProperty.call(MONTH_SEGMENTS, monthSegment)) {
  return apiError(400, 'INVALID_PAYLOAD', 'sf_monthSegment debe ser previous, current o next.', ['sf_monthSegment']);
}

if (!allowedTemplates().includes(templateName)) {
  return apiError(422, 'INVALID_TEMPLATE', 'La plantilla HSM no esta permitida para este ambiente.', [templateName]);
}

const items = Array.isArray(body.items) ? body.items : null;
if (!items || items.length === 0) {
  return apiError(400, 'INVALID_PAYLOAD', 'items debe contener al menos un destinatario.');
}
if (items.length > MAX_ITEMS) {
  return apiError(400, 'INVALID_PAYLOAD', 'El dispatch no puede exceder 1500 destinatarios.', [{ max: MAX_ITEMS, received: items.length }]);
}

const acceptedItems = [];
const rejectedItems = [];
const seen = new Set();

for (let index = 0; index < items.length; index += 1) {
  const item = items[index] || {};
  const sfAccountId = cleanString(item.sf_accountId);
  const sfVehicleId = cleanString(item.sf_vehicleId);
  const sfContractId = cleanString(item.sf_contractId);
  const rawPhone = item.sf_phone;

  if (!sfAccountId || !sfVehicleId || isBlank(rawPhone)) {
    rejectedItems.push(rejectItem(item, 'MISSING_REQUIRED_FIELD'));
    continue;
  }

  const phone = normalizePhone(rawPhone);
  if (!isE164(phone)) {
    rejectedItems.push(rejectItem(item, 'INVALID_PHONE'));
    continue;
  }

  const duplicateKey = sfAccountId + '|' + sfVehicleId;
  if (seen.has(duplicateKey)) {
    rejectedItems.push(rejectItem(item, 'DUPLICATE_KEY_IN_BATCH'));
    continue;
  }
  seen.add(duplicateKey);

  acceptedItems.push({
    item_index: index,
    sf_account_id: sfAccountId,
    sf_vehicle_id: sfVehicleId,
    sf_contract_id: sfContractId || null,
    phone,
    merge_fields: item.mergeFields && typeof item.mergeFields === 'object' && !Array.isArray(item.mergeFields)
      ? item.mergeFields
      : {},
  });
}

const normalizedPayload = {
  sf_dispatch_id: sfDispatchId,
  sf_campaign_id: cleanString(body.sf_campaignId) || null,
  sf_brand: sfBrand,
  campaign_base: MONTH_SEGMENTS[monthSegment],
  template_name: templateName,
  sf_owner_id: sfOwnerId,
  dev_defer_sender: devDeferSender,
  requested_count: items.length,
  rejected_items: rejectedItems,
  items: acceptedItems,
};

return [{
  json: {
    ok: true,
    client_id: providerOAuthAuth.providerClientId,
    sql: INTAKE_SQL,
    query_params: [JSON.stringify(normalizedPayload), providerOAuthAuth.providerClientId, ENDPOINT],
    received: items.length,
    accepted_candidates: acceptedItems.length,
    rejected_candidates: rejectedItems.length,
    normalized_payload: normalizedPayload,
  },
}];

const result = $input.first().json ?? {};

function numberValue(value, fallback = 0) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function parseArray(value) {
  if (Array.isArray(value)) return value;
  if (!value) return [];
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      return [];
    }
  }
  return [];
}

const statusCode = numberValue(result.status_code, 500);
const code = String(result.code || 'INTERNAL_ERROR');
const sfDispatchId = result.sf_dispatch_id || null;
const jobId = result.job_id || null;
const rejectedItems = parseArray(result.rejected_items);
const devDeferSender = result.dev_defer_sender === true || result.dev_defer_sender === 't' || result.dev_defer_sender === 'true';

let body;
if (statusCode === 202 || statusCode === 200) {
  body = {
    job_id: jobId,
    sf_dispatchId: sfDispatchId,
    status: code,
    received: numberValue(result.received),
    accepted: numberValue(result.accepted),
    rejected: numberValue(result.rejected),
    rejectedItems,
    ...(devDeferSender ? { dev_deferred: true } : {}),
  };
} else {
  const details = [];
  if (jobId || sfDispatchId) details.push({ job_id: jobId, sf_dispatchId: sfDispatchId, dispatch_status: result.dispatch_status || null });
  body = {
    code,
    message: result.message || 'Error controlado del dispatch.',
    details,
  };
}

return [{
  json: {
    statusCode,
    body,
    should_trigger_sender: statusCode === 202 && numberValue(result.accepted) > 0 && !devDeferSender,
    sender_payload: { job_id: jobId, sf_dispatchId: sfDispatchId },
  },
}];

const item = $json;
function env(name, fallback = '') { try { return $env[name] || fallback; } catch (e) { return fallback; } }
if (!item.should_trigger_sender) return [{ json: { ...item, sender_triggered: false, sender_skipped: true } }];

const url = env('RENOV_WF02B_SENDER_URL');
if (!url) return [{ json: { ...item, sender_triggered: false, sender_skipped: true, sender_reason: 'RENOV_WF02B_SENDER_URL not configured' } }];

try {
  const token = env('RENOV_INTERNAL_TOKEN');
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url,
    headers: {
      'content-type': 'application/json',
      ...(token ? { authorization: 'Bearer ' + token } : {}),
    },
    body: item.sender_payload,
    json: true,
    simple: false,
    resolveWithFullResponse: true,
    timeout: 3000,
  });
  return [{ json: { ...item, sender_triggered: true, sender_status: response.statusCode || response.status || 0 } }];
} catch (error) {
  return [{ json: { ...item, sender_triggered: false, sender_error: String(error?.message || error) } }];
}
